  window.Webflow.push(() => {
    const targets = document.querySelectorAll("[banner-appear]");

    if (targets.length) {
      gsap.set(targets, { perspective: 2000 });

      gsap.fromTo(targets, 
        { opacity: 0, y: 30 }, 
        {
          opacity: 1,
          y: 0,
          duration: 0.6,
          delay: 0.5,
          ease: "power2.out",
          stagger: {
            each: 0.2,
            from: "start"
          }
        }
      );
    }
  });
</script>



<!-- Banner image load -->

<script>
const banner = document.querySelector('[banner-image="1"]');

gsap.set(banner, {
  scale: 1.3,
  skewX: -3,
  skewY: -2,
  transformPerspective: 2000,
  transformOrigin: "50% 50%"
});

gsap.to(banner, {
  scale: 1.1,
  skewX: 0,
  skewY: 0,
  transformPerspective: 2000,
  duration: 2.5,
  delay: 0,
  ease: "power2.out"
});
</script>
<script src="{{ asset('js/custom-animations.js') }}"></script>
</body></html>
